INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist SQL immer nötig, um Datenbanken anzubinden?', 2, '[{"text": "Nein", "correct": true, "because": "NoSQL oder ORM möglich"}, {"text": "Ja", "correct": false, "because": "Alternativen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit SQL-Abfragen für Datenbanken?', 3, '[{"text": "Datenmanipulation", "correct": true, "because": "Abruf und Änderung ermöglichen"}, {"text": "Datenkompression", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Visualisierung", "correct": false, "because": "UI-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche SQL-Befehle nutze ich für Datenbankfunktionalität?', 5, '[{"text": "SELECT", "correct": true, "because": "Daten abrufen"}, {"text": "INSERT", "correct": true, "because": "Daten hinzufügen"}, {"text": "FORMAT", "correct": false, "because": "Datenformatierung, nicht Kern"}, {"text": "COLOR", "correct": false, "because": "Kein SQL-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SQL-Abfragen können Daten filtern. b) Sie sind nur für relationale DBs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch NoSQL nutzt SQL-ähnliches"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Datenbankanbindung mit SQL?', 4, '[{"text": "Tabellenstruktur", "correct": false, "because": "Grundlage der Abfragen"}, {"text": "Indizes", "correct": false, "because": "Verbessern Performance"}, {"text": "UI-Animationen", "correct": true, "because": "Kein Datenbankaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine SQL-Abfrage auch ohne WHERE effizient ist?', 2, '[{"text": "Nein", "correct": true, "because": "Filterung fehlt, volle Datenmenge"}, {"text": "Ja", "correct": false, "because": "Performance leidet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl nutze ich, um Daten in einer Tabelle zu ändern?', 3, '[{"text": "UPDATE", "correct": true, "because": "Ändert bestehende Einträge"}, {"text": "SELECT", "correct": false, "because": "Nur Abfrage"}, {"text": "DROP", "correct": false, "because": "Löscht Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind für eine gute SQL-Datenbankanbindung wichtig?', 5, '[{"text": "Joins", "correct": true, "because": "Verknüpfen Tabellen"}, {"text": "Indizes", "correct": true, "because": "Beschleunigen Abfragen"}, {"text": "Hohe Farbtiefe", "correct": false, "because": "Irrelevant"}, {"text": "Statische Layouts", "correct": false, "because": "UI-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) SQL-Abfragen können komplexe Daten abrufen. b) Sie sind immer langsam. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Performance optimierbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine SQL-Datenbankanbindung?', 4, '[{"text": "Verbindungsparameter", "correct": false, "because": "Zugang zur DB"}, {"text": "Abfragen", "correct": false, "because": "Kern der Funktionalität"}, {"text": "3D-Grafiken", "correct": true, "because": "Kein Datenbankaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist SELECT nur für Datenabrufe?', 2, '[{"text": "Ja", "correct": true, "because": "Abruf ist Hauptfunktion"}, {"text": "Nein", "correct": false, "because": "Keine Manipulation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken optimieren SQL-Abfragen?', 4, '[{"text": "Indizes", "correct": true, "because": "Schneller Datenzugriff"}, {"text": "Query-Optimierung", "correct": true, "because": "Effizientere Ausführung"}, {"text": "Hohe Auflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass SQL-Abfragen keine Daten ändern können. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "INSERT, UPDATE, DELETE ändern"}, {"text": "Ja", "correct": false, "because": "Nur SELECT abruft"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Datenbankanbindung?', 3, '[{"text": "Abfrageeffizienz", "correct": true, "because": "Verbessert Performance"}, {"text": "Schnelle Visualisierung", "correct": false, "because": "UI-Thema"}, {"text": "Minimaler Code", "correct": false, "because": "Funktion zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Joins verbinden Tabellen. b) SQL ist nur für kleine Datenmengen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SQL skaliert auch groß"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet SQL für Datenbankanbindung?', 5, '[{"text": "Datenkonsistenz", "correct": true, "because": "Transaktionen sichern"}, {"text": "Flexible Abfragen", "correct": true, "because": "Komplexe Daten abrufbar"}, {"text": "Hohe Kompression", "correct": false, "because": "Kein DB-Faktor"}, {"text": "Statische Layouts", "correct": false, "because": "UI-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei SQL-Abfragen unwichtig?', 3, '[{"text": "Datenintegrität", "correct": false, "because": "Kern der Zuverlässigkeit"}, {"text": "Abfrageplan", "correct": false, "because": "Optimierungsfaktor"}, {"text": "Blinkende Cursor", "correct": true, "because": "Kein DB-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich mit SQL auch Tabellen löschen?', 3, '[{"text": "Ja", "correct": true, "because": "DROP löscht Strukturen"}, {"text": "Nein", "correct": false, "because": "Nicht nur Abfragen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SQL-Abfragen auch für Echtzeitdaten geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Optimierung möglich"}, {"text": "Nein", "correct": false, "because": "Echtzeit machbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um Daten hinzuzufügen?', 4, '[{"text": "INSERT", "correct": true, "because": "Fügt neue Datensätze ein"}, {"text": "SELECT", "correct": false, "because": "Nur Abfrage"}, {"text": "FORMAT", "correct": false, "because": "Datenformatierung"}]');
